window.__votdWeek && window.__votdWeek({"week":"2028-12-18","reading":"","days":[{"d":"2028-12-18","ref":"1 Nephi 10:4","b":"1 Nephi","c":10,"v":4,"he":"אַף בְּעוֹד שֵׁשׁ מֵאוֹת שָׁנָה מֵעֵת צֵאת אָבִי מִירוּשָׁלַיִם נָבִיא יָקִים יְהוָה אֱלֹהִים בְּתוֹךְ הַיְּהוּדִים אַף מָשִׁיחַ אוֹ בְּמִלִּים אֲחֵרוֹת מוֹשִׁיעַ הָעוֹלָם׃","en":"Yea, even six hundred years from the time that my father left Jerusalem, a prophet would the Lord God raise up among the Jews—even a Messiah, or, in other words, a Savior of the world."},{"d":"2028-12-19","ref":"1 Nephi 11:13","b":"1 Nephi","c":11,"v":13,"he":"וָאַבִּיט וָאֵרֶא אֶת־הָעִיר הַגְּדוֹלָה יְרוּשָׁלַיִם וְגַם עָרִים אֲחֵרוֹת וָאֵרֶא אֶת־עִיר נָצְרַת וּבְעִיר נָצְרַת וָאֵרֶא עַלְמָה וְהִיא יְפַת־מַרְאֶה וּלְבָנָה עַד־מְאֹד׃","en":"And it came to pass that I looked and beheld the great city of Jerusalem, and also other cities. And I beheld the city of Nazareth; and in the city of Nazareth I beheld a virgin, and she was exceedingly fair and white."},{"d":"2028-12-20","ref":"1 Nephi 11:21","b":"1 Nephi","c":11,"v":21,"he":"וַיֹּאמֶר אֵלַי הַמַּלְאָךְ רְאֵה שֵׂה־אֱלֹהִים אַף בֶּן־אֲבִי עוֹלָם הֲיָדַעְתָּ פִּתְרוֹן הָעֵץ אֲשֶׁר רָאָה אָבִיךָ׃","en":"And the angel said unto me: Behold the Lamb of God, yea, even the Son of the Eternal Father! Knowest thou the meaning of the tree which thy father saw?"},{"d":"2028-12-21","ref":"2 Nephi 25:19","b":"2 Nephi","c":25,"v":19,"he":"כִּי כְדִבְרֵי הַנְּבִיאִים יָבֹא הַמָּשִׁיחַ בְּשֵׁשׁ מֵאוֹת שָׁנָה מֵעֵת צֵאת אָבִי מִירוּשָׁלַיִם וּכְדִבְרֵיהֶם וְגַם דְּבַר מַלְאַךְ אֱלֹהִים יִהְיֶה שְׁמוֹ יֵשׁוּעַ הַמָּשִׁיחַ בֶּן־אֱלֹהִים׃","en":"For according to the words of the prophets, the Messiah cometh in six hundred years from the time that my father left Jerusalem; and according to the words of the prophets, and also the word of the angel of God, his name shall be Jesus Christ, the Son of God."},{"d":"2028-12-22","ref":"Mosiah 15:1","b":"Mosiah","c":15,"v":1,"he":"וַיֹּאמֶר אֲבִינָדִי אֲלֵיהֶם חָפַצְתִּי כִּי תָּבִינוּ כִּי אֱלֹהִים הוּא יֵרֵד בֵּין בְּנֵי־הָאָדָם וְיִגְאַל אֶת־עַמּוֹ׃","en":"And now Abinadi said unto them: I would that ye should understand that God himself shall come down among the children of men, and shall redeem his people."},{"d":"2028-12-23","ref":"Helaman 14:5","b":"Helaman","c":14,"v":5,"he":"וְהִנֵּה יֵרָאֶה כּוֹכָב חָדָשׁ אֲשֶׁר לֹא רְאִיתֶם כָּמוֹהוּ מֵעוֹלָם וְגַם־זֶה יִהְיֶה לָכֶם לְאוֹת׃","en":"And behold, there shall a new star arise, such an one as ye never have beheld; and this also shall be a sign unto you."},{"d":"2028-12-24","ref":"3 Nephi 1:19","b":"3 Nephi","c":1,"v":19,"he":"וַיְהִי כִּי־לֹא הָיָה חֹשֶׁךְ כׇּל־הַלַּיְלָה הַהוּא כִּי־אִם אוֹר כְּצׇהֳרָיִם וַיִּזְרַח הַשֶּׁמֶשׁ בַּבֹּקֶר כְּמִשְׁפָּטוֹ וַיֵּדְעוּ כִּי־זֶה הַיּוֹם אֲשֶׁר יִוָּלֵד בּוֹ יְהוָה בַּעֲבוּר הָאוֹת אֲשֶׁר נִתַּן׃","en":"And it came to pass that there was no darkness in all that night, but it was as light as though it was mid-day. And it came to pass that the sun did rise in the morning again, according to its proper order; and they knew that it was the day that the Lord should be born, because of the sign which had been given."}]});
